/**
 * Unit tests for BasicDeserializerFactory#createTreeDeserializer.
 * Since BasicDeserializerFactory is abstract and has a protected constructor,
 * we use a spy/mock approach or a concrete subclass for testing.
 */
public class BasicDeserializerFactory_createTreeDeserializer_TriageGen2Test {

    private TestableBasicDeserializerFactory factory;
    private DeserializationConfig config;
    private JavaType nodeType;
    private BeanDescription beanDesc;

    // Concrete subclass to allow instantiation and spying on protected methods
    private static class TestableBasicDeserializerFactory extends BasicDeserializerFactory {
        protected TestableBasicDeserializerFactory() {
            super(new DeserializerFactoryConfig());
        }

        @Override
        protected DeserializerFactory withConfig(DeserializerFactoryConfig config) {
            return this;
        }

        // We override this to allow mocking the protected _findCustomTreeNodeDeserializer method
        @Override
        protected JsonDeserializer<?> _findCustomTreeNodeDeserializer(Class<? extends JsonNode> type, 
                DeserializationConfig config, BeanDescription beanDesc) {
            return null; 
        }
    }

    @Before
    public void setUp() {
        factory = spy(new TestableBasicDeserializerFactory());
        config = Mockito.mock(DeserializationConfig.class);
        beanDesc = Mockito.mock(BeanDescription.class);

        // Create a real JavaType for ObjectNode
        ObjectMapper mapper = new ObjectMapper();
        nodeType = mapper.getTypeFactory().constructType(ObjectNode.class);
    }

    /**
     * Test Case 1: When a custom deserializer is found via _findCustomTreeNodeDeserializer.
     * This covers the branch: if (custom != null) { return custom; }
     */
    @Test
    public void testCreateTreeDeserializer_ReturnsCustomDeserializer() throws Exception {
        JsonDeserializer<?> customDeserializer = Mockito.mock(JsonDeserializer.class);

        // Mock the protected method to return our custom deserializer
        when(factory._findCustomTreeNodeDeserializer(eq(ObjectNode.class), eq(config), eq(beanDesc)))
                .thenReturn(customDeserializer);

        JsonDeserializer<?> result = factory.createTreeDeserializer(config, nodeType, beanDesc);

        assertNotNull("Result should not be null", result);
        assertEquals("Should return the custom deserializer", customDeserializer, result);
    }

    /**
     * Test Case 2: When no custom deserializer is found.
     * This covers the branch: return JsonNodeDeserializer.getDeserializer(nodeClass);
     */
    @Test
    public void testCreateTreeDeserializer_ReturnsDefaultDeserializer() throws Exception {
        // Mock the protected method to return null
        when(factory._findCustomTreeNodeDeserializer(eq(ObjectNode.class), eq(config), eq(beanDesc)))
                .thenReturn(null);

        JsonDeserializer<?> result = factory.createTreeDeserializer(config, nodeType, beanDesc);

        assertNotNull("Result should not be null", result);
        // JsonNodeDeserializer.getDeserializer(ObjectNode.class) returns a standard deserializer
        // We verify it's not the custom one we mocked
        assertEquals("Should return the default JsonNodeDeserializer", 
                JsonNodeDeserializer.getDeserializer(ObjectNode.class), result);
    }

    /**
     * Test Case 3: Verify that the raw class is correctly extracted from JavaType.
     */
    @Test
    public void testCreateTreeDeserializer_CorrectClassExtraction() throws Exception {
        // Using a different JsonNode type
        JavaType arrayNodeType = new ObjectMapper().getTypeFactory().constructType(com.fasterxml.jackson.databind.node.ArrayNode.class);

        when(factory._findCustomTreeNodeDeserializer(eq(com.fasterxml.jackson.databind.node.ArrayNode.class), eq(config), eq(beanDesc)))
                .thenReturn(null);

        JsonDeserializer<?> result = factory.createTreeDeserializer(config, arrayNodeType, beanDesc);

        assertNotNull(result);
        // Verify that the internal call used the correct class
        // The default deserializer for ArrayNode is different from ObjectNode
        assertEquals(JsonNodeDeserializer.getDeserializer(com.fasterxml.jackson.databind.node.ArrayNode.class), result);
    }
}
